import{_ as o,o as a,c,a5 as t}from"./chunks/framework.DJo0M80U.js";const f=JSON.parse('{"title":"稳妥构造函数模式","description":"道格拉斯 克罗克福德 (Douglas Crockford) 发明了 Javascript 中的稳妥对象 (durable objects) 这个概念。 基本思路是：在创建对象时传入的初始化值，并不作为属性添加到要返回的对象上，而是都在稳妥构造函数中指定了特定的修改和访问方法。这。","frontmatter":{"title":"稳妥构造函数模式","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","对象、数组与函数"],"description":"道格拉斯 克罗克福德 (Douglas Crockford) 发明了 Javascript 中的稳妥对象 (durable objects) 这个概念。 基本思路是：在创建对象时传入的初始化值，并不作为属性添加到要返回的对象上，而是都在稳妥构造函数中指定了特定的修改和访问方法。这。","sidebarWeight":165,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/面向对象程序设计/(90M)创建对象/(10m)稳妥构造函数模式.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/03-对象、数组与函数/(90M)创建对象/(10m)稳妥构造函数模式.md","filePath":"posts/JavaScript系统教程/03-对象、数组与函数/(90M)创建对象/(10m)稳妥构造函数模式.md"}'),d={name:"posts/JavaScript系统教程/03-对象、数组与函数/(90M)创建对象/(10m)稳妥构造函数模式.md"};function s(r,e,i,n,p,l){return a(),c("div",null,[...e[0]||(e[0]=[t('<div><h1 id="稳妥构造函数模式" tabindex="-1">稳妥构造函数模式 <a class="header-anchor" href="#稳妥构造函数模式" aria-label="Permalink to &quot;稳妥构造函数模式&quot;">​</a></h1><blockquote><p>本节目标：理解“稳妥构造函数模式”的核心思路，并能把它用于实际开发或面试表达。 道格拉斯<code>*</code>克罗克福德<code>(Douglas Crockford)</code>发明了<code>Javascript</code>中的稳妥对象<code>(durable objects)</code>这个概念。</p></blockquote><p>基本思路是：在创建对象时传入的初始化值，并不作为属性添加到要返回的对象上，而是都在稳妥构造函数中指定了特定的修改和访问方法。这些初始值除了以指定的方法进行修改和访问，没有其它方法可以操作。</p><p>这个模式创建的所谓稳妥对象：</p><ul><li>它是没有公共属性（没有给对象添加属性的代码）；</li><li>它只有一些访问内部值的方法，且方法也不引用<code>this</code>。</li><li>稳妥对象最适合在一些安全的环境中（这些环境中会禁止使用<code>this</code>和<code>new</code>），或者在防止数据被其它应用程序（如<code>Mashup</code>程序）改动时使用。</li></ul><p>稳妥构造函数遵循与寄生构造函数类似的模式，但有两点不同： 一是新创建对象的实例方法不引用<code>this</code>； 二是不使用<code>new</code>操作符调用构造函数。 三是稳妥对象只有私有属性，只能通过定义的方法去访问(闭包方式)，没有其他方式访问。 这样相当于有了一种创建只有私有属性和访问私有属性方法的对象(稳妥对象)方法。</p><p>按照稳妥构造函数的要求，可以将前面的<code>Person</code>构造函数重写如下。 function Person(name) { //创建要返回的对象 var o = new Object(); //可以在这里定义私有变量和函数 //添加方法 o.setName = function () { name *= 2 } o.sayName = function () { console.log(name); } //返回对象 return o; } var friend = Person(22); friend.setName() friend.sayName();//44</p><p>变量<code>friend</code>中保存的是一个稳妥对象，除了调用指定的<code>sayName()</code>等方法外，没有别的方式可以访问其数据成员。因为传入构造函数的初始值并没有放在对象的属性上，而是让特定的函数通过闭包来访问；</p><p>即使有其他代码会给这个对象添加方法或数据成员，但也不可能有别的办法访问传入到构造函数中的原始数据。</p><p>稳妥构造函数模式提供的这种安全性，使得它非常适合在某些安全执行环境，例如<code>Adsafe(www.adsafe.org)</code>和<code>Caja(http://code.google.com/p/google-caja/)</code>提供的环境下使用。</p><p>与寄生构造函数类似，使用稳妥构造函数模式创建的对象与构造函数之间也没什么关系，因此，<code>instanceof</code>操作符对这种对象也没有意义。</p></div>',1)])])}const m=o(d,[["render",s]]);export{f as __pageData,m as default};
